CREATE TABLE offices (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,slug VARCHAR(80) NOT NULL UNIQUE,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE services (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,office_id BIGINT UNSIGNED NOT NULL,code VARCHAR(8) NOT NULL,name VARCHAR(120) NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_service_code(office_id,code),CONSTRAINT fk_services_office FOREIGN KEY(office_id) REFERENCES offices(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE counters (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,office_id BIGINT UNSIGNED NOT NULL,service_id BIGINT UNSIGNED NOT NULL,code VARCHAR(12) NOT NULL,name VARCHAR(80) NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,UNIQUE KEY uq_counter_code(office_id,code),CONSTRAINT fk_counters_office FOREIGN KEY(office_id) REFERENCES offices(id),CONSTRAINT fk_counters_service FOREIGN KEY(service_id) REFERENCES services(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,office_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,username VARCHAR(80) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','operator') NOT NULL DEFAULT 'operator',active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_users_office FOREIGN KEY(office_id) REFERENCES offices(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE tickets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,office_id BIGINT UNSIGNED NOT NULL,service_id BIGINT UNSIGNED NOT NULL,counter_id BIGINT UNSIGNED NULL,ticket_date DATE NOT NULL,ticket_no VARCHAR(24) NOT NULL,tracking_code CHAR(24) NOT NULL UNIQUE,queue_order BIGINT UNSIGNED NOT NULL,status ENUM('waiting','called','done','absent') NOT NULL DEFAULT 'waiting',callback TINYINT(1) NOT NULL DEFAULT 0,call_count SMALLINT UNSIGNED NOT NULL DEFAULT 0,issued_at DATETIME NOT NULL,called_at DATETIME NULL,completed_at DATETIME NULL,returned_at DATETIME NULL,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_ticket_day(office_id,service_id,ticket_date,ticket_no),KEY idx_ticket_queue(office_id,service_id,ticket_date,status,queue_order),CONSTRAINT fk_tickets_office FOREIGN KEY(office_id) REFERENCES offices(id),CONSTRAINT fk_tickets_service FOREIGN KEY(service_id) REFERENCES services(id),CONSTRAINT fk_tickets_counter FOREIGN KEY(counter_id) REFERENCES counters(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE daily_sequences (office_id BIGINT UNSIGNED NOT NULL,service_id BIGINT UNSIGNED NOT NULL,ticket_date DATE NOT NULL,last_number INT UNSIGNED NOT NULL DEFAULT 0,last_queue BIGINT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY(office_id,service_id,ticket_date),CONSTRAINT fk_seq_office FOREIGN KEY(office_id) REFERENCES offices(id),CONSTRAINT fk_seq_service FOREIGN KEY(service_id) REFERENCES services(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
